2111  stream_parse_key(pgp_source_t *src, pgp_key_pkt_t *key)
  2112  {
  2113      pgp_packet_body_t pkt;
  2114      rnp_result_t      res;
  2115      int               tag;
  2116      uint8_t           alg = 0;
  2117      uint8_t           ver = 0;
  2118
  2119      /* check the key tag */
  2120      tag = stream_pkt_type(src);
  2121      if (!is_key_pkt(tag)) {
  2122          RNP_LOG("wrong key packet tag: %d", tag);
  2123          return RNP_ERROR_BAD_FORMAT;
  2124      }
  2125
  2126      /* Read the packet into memory */
  2127      if ((res = stream_read_packet_body(src, &pkt))) {
  2128          return res;
  2129      }
  2130
  2131      res = RNP_ERROR_BAD_FORMAT;
  2132      memset(key, 0, sizeof(*key));
  2133
  2134      /* key type, i.e. tag */
  2135      key->tag = pkt.tag;
  2136
  2137      /* version */
  2138      if (!get_packet_body_byte(&pkt, &ver) || (ver < PGP_V2) || (ver > PGP_V4)) {
  2139          RNP_LOG("wrong key packet version");
  2140          goto finish;
  2141      }
  2142      key->version = (pgp_version_t) ver;
  2143
  2144      /* creation time */
  2145      if (!get_packet_body_uint32(&pkt, &key->creation_time)) {
  2146          goto finish;
  2147      }
  2148
  2149      /* v3: validity days */
  2150      if ((key->version < PGP_V4) && !get_packet_body_uint16(&pkt, &key->v3_days)) {
  2151          goto finish;
  2152      }
  2153
  2154      /* key algorithm */
  2155      if (!get_packet_body_byte(&pkt, &alg)) {
  2156          goto finish;
  2157      }
  2158      key->alg = (pgp_pubkey_alg_t) alg;
  2159      key->material.alg = (pgp_pubkey_alg_t) alg;
  2160
  2161      /* v3 keys must be RSA-only */
  2162      if ((key->version < PGP_V4) && !is_rsa_key_alg(key->alg)) {
  2163          RNP_LOG("wrong v3 pk algorithm");
  2164          goto finish;
  2165      }
  2166
  2167      /* algorithm specific fields */
  2168      switch (key->alg) {
  2169      case PGP_PKA_RSA:
  2170      case PGP_PKA_RSA_ENCRYPT_ONLY:
  2171      case PGP_PKA_RSA_SIGN_ONLY:
  2172          if (!get_packet_body_mpi(&pkt, &key->material.rsa.n) ||
  2173              !get_packet_body_mpi(&pkt, &key->material.rsa.e)) {
  2174              goto finish;
  2175          }
  2176          break;
  2177      case PGP_PKA_DSA:
  2178          if (!get_packet_body_mpi(&pkt, &key->material.dsa.p) ||
  2179              !get_packet_body_mpi(&pkt, &key->material.dsa.q) ||
  2180              !get_packet_body_mpi(&pkt, &key->material.dsa.g) ||
  2181              !get_packet_body_mpi(&pkt, &key->material.dsa.y)) {
  2182              goto finish;
  2183          }
  2184          break;
  2185      case PGP_PKA_ELGAMAL:
  2186      case PGP_PKA_ELGAMAL_ENCRYPT_OR_SIGN:
  2187          if (!get_packet_body_mpi(&pkt, &key->material.eg.p) ||
  2188              !get_packet_body_mpi(&pkt, &key->material.eg.g) ||
  2189              !get_packet_body_mpi(&pkt, &key->material.eg.y)) {
  2190              goto finish;
  2191          }
  2192          break;
  2193      case PGP_PKA_ECDSA:
  2194      case PGP_PKA_EDDSA:
  2195      case PGP_PKA_SM2:
  2196          if (!get_packet_body_key_curve(&pkt, &key->material.ec.curve) ||
  2197              !get_packet_body_mpi(&pkt, &key->material.ec.p)) {
  2198              goto finish;
  2199          }
  2200          break;
